        if(!in_array($kind,['comunidade','trocas'],true))throw new PlatformProblem(400,'invalid_terms_kind');
        $d=['kind'=>$kind,'version'=>'2026-10-18.2','title'=>$kind==='trocas'?'Termos de Trocas e vendas':'Regras de participação da comunidade','status'=>'Minuta para teste local — revisão jurídica pendente','sections'=>$kind==='trocas'?$market:$common];
        $d['hash']=hash('sha256',json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return $d;
    }
